import{_ as i,C as n,o as p,c,j as a,a as o,E as r,a2 as d}from"./chunks/framework.D8ABcfAn.js";const y=JSON.parse('{"title":"Architektúra","description":"Ako ApiPresenter v Nette API 3.x spracuje požiadavku: endpoint, obmedzenie požiadaviek, parametre, autorizácia, handler, kontrola výstupu a logovanie.","frontmatter":{"title":"Architektúra","description":"Ako ApiPresenter v Nette API 3.x spracuje požiadavku: endpoint, obmedzenie požiadaviek, parametre, autorizácia, handler, kontrola výstupu a logovanie."},"headers":[],"relativePath":"sk/guide/architecture.md","filePath":"sk/guide/architecture.md","lastUpdated":1793093528000}'),s={name:"sk/guide/architecture.md"};function l(h,e,v,k,u,m){const t=n("Diagram");return p(),c("div",null,[e[0]||(e[0]=a("h1",{id:"architektura",tabindex:"-1"},[o("Architektúra "),a("a",{class:"header-anchor",href:"#architektura","aria-label":'Permalink to "Architektúra"'},"​")],-1)),e[1]||(e[1]=a("p",null,[o("Každá API požiadavka ide do jedného presentera, "),a("code",null,"Tomaj\\NetteApi\\Presenters\\ApiPresenter"),o(". Ten sa spýta "),a("code",null,"ApiDecider"),o(", ktorý endpoint sa zhoduje, spustí kontroly v pevnom poradí a vráti to, čo vytvoril handler alebo "),a("code",null,"error handler"),o(".")],-1)),r(t,{name:"architecture-1",alt:"Požiadavka, ApiDecider, obmedzenie požiadaviek, autorizácia, hlásenie chýb parametrov (400), handler, kontrola výstupnej schémy, odpoveď a logger, s výstupmi 429, 401 a 400 a 404 z DefaultHandlera (zalogovaná); každá odpoveď sa vráti klientovi"}),e[2]||(e[2]=d('<h2 id="casti" tabindex="-1">Časti <a class="header-anchor" href="#casti" aria-label="Permalink to &quot;Časti&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Časť</th><th>Trieda alebo rozhranie</th><th>Úloha</th></tr></thead><tbody><tr><td>Presenter</td><td><code>ApiPresenter</code></td><td>Spúšťa všetky kroky nižšie. Je <code>final</code>.</td></tr><tr><td>Zoznam endpointov</td><td><code>ApiDecider</code></td><td><code>addApi()</code> registruje endpointy, <code>getApi()</code> nájde ten pre požiadavku.</td></tr><tr><td>Endpoint</td><td><code>EndpointIdentifier</code></td><td>Metóda, verzia, balík a voliteľná akcia.</td></tr><tr><td>Handler</td><td><code>ApiHandlerInterface</code>, zvyčajne <code>BaseHandler</code></td><td>Deklaruje parametre a výstupy, robí samotnú prácu.</td></tr><tr><td>Autorizácia</td><td><code>ApiAuthorizationInterface</code></td><td>Rozhodne, či požiadavka smie bežať.</td></tr><tr><td>Obmedzenie požiadaviek</td><td><code>RateLimitInterface</code></td><td>Voliteľné, pre každý endpoint.</td></tr><tr><td>Chyby</td><td><code>ErrorHandlerInterface</code>, <code>DefaultErrorHandler</code></td><td>Zmení zlyhania na JSON odpovede.</td></tr><tr><td>Kontrola výstupov</td><td><code>ConfiguratorInterface</code></td><td>Rozhodne, či sa výstupy validujú a zobrazujú detaily chýb.</td></tr><tr><td>Logger</td><td><code>ApiLoggerInterface</code></td><td>Voliteľný, hľadá sa v DI kontajneri.</td></tr></tbody></table><h2 id="poradie-krokov" tabindex="-1">Poradie krokov <a class="header-anchor" href="#poradie-krokov" aria-label="Permalink to &quot;Poradie krokov&quot;">​</a></h2><p>Stručne: CORS hlavičky, nájdenie endpointu (<code>404</code>), obmedzenie požiadaviek (<code>429</code>), načítanie parametrov, autorizácia (<code>401</code>), chyby parametrov (<code>400</code>), handler, kontrola výstupu (<code>500</code>) a logovanie. Parametre sa načítajú pred autorizáciou, ich chyby sa však hlásia až po nej, takže volajúci bez prístupu dostane <code>401</code> a žiadne podrobnosti o parametroch.</p><p>Celé poradie s kódom a výstupom každého kroku je na jednej stránke: <a href="/nette-api/pr-preview/pr-210/sk/guide/presenter.html">Spracovanie v ApiPresenteri</a>.</p>',5)),r(t,{name:"architecture-2",alt:"Priebeh POST požiadavky: autorizácia, potom chyby parametrov (načítaných pred ňou) a handler, každý s chybovou vetvou cez error handler"}),e[3]||(e[3]=d('<div class="warning custom-block"><p class="custom-block-title">Nie každá odpoveď sa loguje</p><p>Kroky obmedzenia požiadaviek, autorizácie a chýb parametrov skončia predčasne, takže <code>429</code>, <code>401</code>, <code>400</code> a <code>500</code> zo zlyhanej autorizácie sa v 3.x k loggeru nedostanú. <code>404</code>, odpovede handlera a chyby handlera alebo výstupu sa logujú.</p></div><h2 id="caste-otazky" tabindex="-1">Časté otázky <a class="header-anchor" href="#caste-otazky" aria-label="Permalink to &quot;Časté otázky&quot;">​</a></h2><h3 id="mozem-apipresenter-nahradit-vlastnym-presenterom" tabindex="-1">Môžem ApiPresenter nahradiť vlastným presenterom? <a class="header-anchor" href="#mozem-apipresenter-nahradit-vlastnym-presenterom" aria-label="Permalink to &quot;Môžem ApiPresenter nahradiť vlastným presenterom?&quot;">​</a></h3><p>Nie dedením, trieda je <code>final</code>. Môžete ho nakonfigurovať (<code>setCorsHeader()</code>) a vymeniť jeho závislosti: <code>error handler</code>, konfigurátor a logger. Pozrite si <a href="/nette-api/pr-preview/pr-210/sk/guide/errors.html">Spracovanie chýb</a>.</p><h3 id="preco-poziadavka-so-zlym-tokenom-aj-zlymi-parametrami-vrati-401-a-nie-400" tabindex="-1">Prečo požiadavka so zlým tokenom aj zlými parametrami vráti 401 a nie 400? <a class="header-anchor" href="#preco-poziadavka-so-zlym-tokenom-aj-zlymi-parametrami-vrati-401-a-nie-400" aria-label="Permalink to &quot;Prečo požiadavka so zlým tokenom aj zlými parametrami vráti 401 a nie 400?&quot;">​</a></h3><p>Autorizácia beží skôr, ako sa nahlásia chyby parametrov. Pozrite si krok 6 vyššie a stránku <a href="/nette-api/pr-preview/pr-210/sk/guide/authorization.html">Autorizácia</a>.</p><h3 id="vytvara-sa-handler-kazdeho-endpointu-pri-kazdej-poziadavke" tabindex="-1">Vytvára sa handler každého endpointu pri každej požiadavke? <a class="header-anchor" href="#vytvara-sa-handler-kazdeho-endpointu-pri-kazdej-poziadavke" aria-label="Permalink to &quot;Vytvára sa handler každého endpointu pri každej požiadavke?&quot;">​</a></h3><p>Nie. Keď do <code>addApi()</code> odovzdáte názov triedy, handler sa vezme z DI kontajnera až pri volaní jeho endpointu. Pozrite si <a href="/nette-api/pr-preview/pr-210/sk/guide/handlers.html#registracia-handlera">Handlery</a>.</p><h3 id="ako-vyzera-odpoved-neznameho-endpointu" tabindex="-1">Ako vyzerá odpoveď neznámeho endpointu? <a class="header-anchor" href="#ako-vyzera-odpoved-neznameho-endpointu" aria-label="Permalink to &quot;Ako vyzerá odpoveď neznámeho endpointu?&quot;">​</a></h3><p><code>404</code> s <code>{&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;Unknown api endpoint&quot;}</code>. Testuje to <a href="/nette-api/pr-preview/pr-210/sk/examples/hello-world.html">príklad hello world</a>.</p><h3 id="kde-najdem-vsetky-triedy-v-jednom-zozname" tabindex="-1">Kde nájdem všetky triedy v jednom zozname? <a class="header-anchor" href="#kde-najdem-vsetky-triedy-v-jednom-zozname" aria-label="Permalink to &quot;Kde nájdem všetky triedy v jednom zozname?&quot;">​</a></h3><p>V <a href="/nette-api/pr-preview/pr-210/sk/api/reference.html">Referencii</a>.</p>',12))])}const b=i(s,[["render",l]]);export{y as __pageData,b as default};
